# Example: Defining a hotel tool for LangChain agent
from langchain.tools import tool
import requests

@tool
def check_room_availability(check_in: str, check_out: str, room_type: str) -> dict:
    """Query PMS API for room availability in date range."""
    response = requests.post(
        "https://pms.hotel.com/api/availability",
        json={"check_in": check_in, "check_out": check_out, "room_type": room_type},
        headers={"Authorization": "Bearer TOKEN"}
    )
    return response.json()  # {"available": true, "rate": 299.00}

# Example: Event-driven workflow for service recovery
from datetime import datetime, timedelta

def detect_service_lag(order_time: datetime, current_time: datetime, threshold_minutes: int = 30) -> dict:
    """Trigger proactive compensation if room service exceeds threshold."""
    lag = (current_time - order_time).total_seconds() / 60
    if lag > threshold_minutes:
        return {
            "action": "offer_compensation",
            "message": "We apologize for the delay. Please accept a complimentary dessert.",
            "log_ticket": True,
            "notify_manager": True
        }
    return {"action": "monitor"}

