# Function calling for PMS integration with error handling
from anthropic import Anthropic
import requests
from datetime import datetime

tools = [{
    "name": "check_availability",
    "description": "Check room availability in PMS for given dates",
    "input_schema": {
        "type": "object",
        "properties": {
            "check_in": {"type": "string", "format": "date"},
            "check_out": {"type": "string", "format": "date"},
            "room_type": {"type": "string"},
            "guests": {"type": "integer"}
        },
        "required": ["check_in", "check_out", "guests"]
    }
}]

def execute_tool(tool_name, tool_input):
    if tool_name == "check_availability":
        try:
            # Call PMS API with OAuth token from vault
            response = requests.post(
                "https://pms-api.hotel.com/availability",
                headers={"Authorization": f"Bearer {get_secure_token()}"},
                json=tool_input,
                timeout=2
            )
            response.raise_for_status()
            return response.json()
        except requests.exceptions.Timeout:
            return {"error": "PMS temporarily unavailable", "fallback": True}
        except requests.exceptions.HTTPError as e:
            if e.response.status_code == 409:
                return {"error": "No availability for selected dates"}
            raise

# Agent orchestration loop
client = Anthropic()
response = client.messages.create(
    model="claude-3-5-sonnet-20241022",
    max_tokens=1024,
    tools=tools,
    messages=[{"role": "user", "content": "Do you have a king room available Dec 15-17?"}]
)

if response.stop_reason == "tool_use":
    tool_result = execute_tool(response.content[1].name, response.content[1].input)
    # Continue conversation with tool results...
